WITH fato AS (SELECT count(*) AS n,count(DISTINCT id_resultado) AS ids,count(DISTINCT id_evento) AS eventos,count(*) FILTER(WHERE id_localidade=0) AS sem_localidade FROM public.tbbi_fat_perfil_br_2026),
original AS(SELECT count(*) AS n FROM public.vwbi_fat_perfil_br_2026),
adaptado AS(SELECT count(*) AS n,count(DISTINCT id_resultado) AS ids FROM estudo.vwbi_perfil_br_2026),
resultados AS(SELECT count(*) AS n,count(DISTINCT id_resultado) AS ids,count(*) FILTER(WHERE status_final=0 AND homologado IS TRUE AND concluinte IS TRUE) AS elegiveis FROM estudo.vw_resultados_2026),
validacao AS(SELECT count(*) FILTER(WHERE r.id_resultado IS NULL) AS sem_resultado,count(*) FILTER(WHERE e.pais IS DISTINCT FROM 'BR' OR r.status_final IS DISTINCT FROM 0 OR r.homologado IS NOT TRUE OR r.concluinte IS NOT TRUE OR f.data_evento IS DISTINCT FROM e.data_final OR f.data_evento<DATE '2026-01-01' OR f.data_evento>=DATE '2026-10-01') AS divergencias FROM public.tbbi_fat_perfil_br_2026 f LEFT JOIN public.tb_resultados r USING(id_resultado) LEFT JOIN public.tb_evento_corridas e ON e.id_evento=f.id_evento),
geracoes AS(SELECT id_geracao,count(*) AS participacoes FROM public.tbbi_fat_perfil_br_2026 GROUP BY id_geracao)
SELECT jsonb_build_object('capturado_em',transaction_timestamp(),'fato',(SELECT to_jsonb(f) FROM fato f),'view_original',(SELECT to_jsonb(o) FROM original o),'view_estudo',(SELECT to_jsonb(a) FROM adaptado a),'resultados_estudo',(SELECT to_jsonb(r) FROM resultados r),'validacao',(SELECT to_jsonb(v) FROM validacao v),'geracoes',(SELECT jsonb_agg(to_jsonb(g) ORDER BY id_geracao) FROM geracoes g)) AS payload;